let d='<defs>'+cs.map(c=>'<clipPath id="vc'+c[0]+'"><circle cx="'+c[1]+'" cy="'+c[2]+'" r="'+R+'"/></clipPath>').join('')+'</defs>';
d+='<rect x="2" y="2" width="296" height="236" '+ST+'/>';
