const tree=(()=>{const node=(x,y,l)=>'<circle cx="'+x+'" cy="'+y+'" r="15" fill="var(--sheet,#fff)" '+ST+'/>'+T(x,y+4,l);
const leaf=(x,y,l)=>'<rect x="'+(x-13)+'" y="'+(y-13)+'" width="26" height="26" fill="var(--sheet,#fff)" '+ST+'/>'+T(x,y+4,l);
const ln=(a,b,l,dx)=>'<line x1="'+a[0]+'" y1="'+(a[1]+15)+'" x2="'+b[0]+'" y2="'+(b[1]-14)+'" '+ST+'/>'+T((a[0]+b[0])/2+(dx||0),(a[1]+b[1])/2+2,l);
const X1=[230,28],X3=[110,95],L1=[230,95],X2=[345,95],a=[60,165],b=[160,165],c=[290,165],d=[350,165],X4=[415,165],e=[385,230],f=[445,230];
const g=ln(X1,X3,'a',-8)+ln(X1,L1,'b',8)+ln(X1,X2,'c',10)+ln(X3,a,'<=35',-14)+ln(X3,b,'>35',14)+ln(X2,c,'P',-8)+ln(X2,d,'M',9)+ln(X2,X4,'G',14)+ln(X4,e,'não',-14)+ln(X4,f,'sim',14);
return wrap('0 0 480 250',g+node(X1[0],X1[1],'X1')+node(X3[0],X3[1],'X3')+leaf(L1[0],L1[1],'1')+node(X2[0],X2[1],'X2')+leaf(a[0],a[1],'1')+leaf(b[0],b[1],'2')+leaf(c[0],c[1],'1')+leaf(d[0],d[1],'2')+node(X4[0],X4[1],'X4')+leaf(e[0],e[1],'2')+leaf(f[0],f[1],'1'),
 'Árvore de decisão. A raiz é X1: se X1 é a, vai para X3 (X3 menor ou igual a 35 dá classe 1; maior que 35 dá classe 2); se X1 é b, classe 1; se X1 é c, vai para X2 (P dá classe 1, M dá classe 2, G vai para X4: não dá classe 2, sim dá classe 1).').replace('class="qfig"','class="qfig wide"')})();
